def md(text: str) -> dict:
    return {"cell_type":"markdown","metadata":{},"source":text.splitlines(keepends=True)}

def code(text: str) -> dict:
    return {"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":text.splitlines(keepends=True)}

def spanish_code(program: str) -> str:
    """Translate notebook-facing comments and labels while leaving pipeline identifiers untouched."""
    labels = {
        "family:": "familia:", "throughput:": "caudal:", "feed F80:": "F80 de alimentación:",
        "product P80:": "P80 de producto:", "grinding energy:": "energía de molienda:",
        "Virtual batch": "Batch virtual", "Continuous bank": "Banco continuo",
        "Continuous-bank profile": "Perfil del banco continuo", "Virtual batch test": "Prueba batch virtual",
        "Batch time (min)": "Tiempo batch (min)", "Bank cell number": "Número de celda",
        "Payable recovery (%)": "Recuperación del payable (%)", "Residence time (min)": "Tiempo de residencia (min)",
        "Stream": "Flujo", "Solids (t/h)": "Sólidos (t/h)", "RMSE (points)": "RMSE (puntos)",
        "batch RMSE (points)": "RMSE batch (puntos)", "bank prediction (%)": "Predicción del banco (%)",
        "bank error (points)": "Error de banco (puntos)", "extrapolation gap (points)": "Brecha de extrapolación (puntos)",
        "engine version:": "versión del motor:", "design matrix:": "matriz de diseño:",
        "rows by case:": "filas por caso:", "case folds:": "folds por caso:",
        "GP nominal 95% interval coverage:": "cobertura nominal 95% del intervalo GP:",
        "Interpolation RMSE by target (target units differ)": "RMSE de interpolación por objetivo (las unidades difieren)",
        "RMSE in target units": "RMSE en unidades del objetivo",
    }
    out = []
    for line in program.splitlines():
        if line.lstrip().startswith("#"):
            out.append("# Paso ejecutable del método OreFlow explicado en la celda anterior.")
            continue
        for source, target in labels.items():
            line = line.replace(source, target)
        out.append(line)
    return "\n".join(out)

def lesson_doc(language: str, topic: str, number: int, lesson: dict) -> dict:
    es = language == "es"
    title = lesson["title"]
    prereq = lesson["prereq"]
    opening = (f"# {title}\n\nNivel: {number}. Requisitos previos: {prereq} Tiempo de lectura: {lesson['mins']} minutos."
               if es else f"# {title}\n\nLevel: {number}. Prerequisites: {prereq} Reading time: {lesson['mins']} minutes.")
    setup_heading = "Preparación" if es else "Setup"
    pins = " ".join(PINS)
    install = f"```bash\npip install {pins}\n```\n\nEl pipeline OreFlow se importa desde `data-pipeline/`; este notebook nunca instala paquetes." if es else f"```bash\npip install {pins}\n```\n\nThe OreFlow pipeline is imported from `data-pipeline/`; this notebook never installs packages."
    imports = ("# Importa herramientas de análisis y registra sus versiones exactas.\nimport importlib.metadata\nimport json\nfrom pathlib import Path\nimport sys\nimport numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\n\n# Resuelve el pipeline local desde la estructura relativa del repositorio.\nrepo = Path('../../../').resolve()\nsys.path.insert(0, str(repo / 'data-pipeline'))\nfor package in ('numpy', 'scipy', 'pandas', 'matplotlib', 'nbclient', 'nbformat', 'ipykernel'):\n    print(package, importlib.metadata.version(package))"
               if es else "# Import analysis tools and record their exact versions.\nimport importlib.metadata\nimport json\nfrom pathlib import Path\nimport sys\nimport numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\n\n# Resolve the local pipeline from the repository-relative layout.\nrepo = Path('../../../').resolve()\nsys.path.insert(0, str(repo / 'data-pipeline'))\nfor package in ('numpy', 'scipy', 'pandas', 'matplotlib', 'nbclient', 'nbformat', 'ipykernel'):\n    print(package, importlib.metadata.version(package))")
    objective_h = "Objetivos" if es else "Objectives"
    data_h = "Datos" if es else "Data"
    method_h = "Método" if es else "Method"
    results_h = "Resultados" if es else "Results"
    summary_h = "Resumen" if es else "Summary"
    refs_h = "Referencias" if es else "References"
    cells = [md(opening), md(f"## {objective_h}\n\n{lesson['objective']}"), md(f"## {setup_heading}\n\n{install}"), md("Configura las importaciones y registra versiones. Este paso hace reproducible la ejecución del método." if es else "Configure imports and record versions. This makes the method run reproducible."), code(imports), md(f"## {data_h}\n\n{lesson['data']}"), md(f"## {method_h}\n\n{lesson['method']}")]
    if "sota" in lesson and not es:
        cells.append(md(f"## State of the art\n\n{lesson['sota']}"))
    if "sota" in lesson and es:
        cells.append(md(f"## Estado del arte\n\n{lesson['sota']}"))
    lesson_cells = lesson["cells"] or (LESSONS[topic]["en"][number - 1]["cells"] if es else [])
    for instruction, program in lesson_cells:
        # Instruction pairs are authored in (English, Spanish) order.
        explanation = instruction[1] if es else instruction[0]
        if es:
            program = spanish_code(program)
        if not any(line.lstrip().startswith("#") for line in program.splitlines()):
            program = "# " + explanation.split(".")[0].strip() + ".\n" + program
        cells.extend([md(explanation), code(program)])
    cells.extend([md(f"## {results_h}\n\n{lesson['results']}"), md(f"## {summary_h}\n\n{lesson['summary']}"), md(f"## {refs_h}\n\n" + "\n".join(f"- {url}" for url in lesson["refs"]))])
    for index, cell in enumerate(cells, 1):
        cell["id"] = f"cell-{index:02d}"
    metadata = {"kernelspec":{"display_name":"Python 3","language":"python","name":"python3"},
                "language_info":{"name":"python","version":"3.12"},
                "caos":{"language":language,"topic":topic,"level":number,"title":title,"packages":PINS,
                        "data":lesson["data_files"],"sources":lesson["refs"],"beyond":[]}}
    return {"cells":cells,"metadata":metadata,"nbformat":4,"nbformat_minor":5}

def main() -> None:
    (ROOT / "notebooks/requirements.txt").write_text("# Exact pins for OreFlow's pipeline-backed bilingual lessons.\n" + "\n".join(PINS) + "\n", encoding="utf-8")
    for language in ("en", "es"):
        heading = "# OreFlow notebooks\n\n" if language == "en" else "# Notebooks OreFlow\n\n"
        intro = ("Bilingual practical lessons grounded in OreFlow's committed process cases and implemented pipeline methods.\n\n"
                 if language == "en" else "Lecciones prácticas bilingües basadas en casos comprometidos y métodos implementados en el pipeline OreFlow.\n\n")
        sections = [heading + intro]
        for topic_number, (topic, spec) in enumerate(LESSONS.items(), 1):
            sections.append(f"## {topic_number:02d} {topic}\n")
            for level, lesson in enumerate(spec[language], 1):
                lesson["data_files"] = spec["files"]
                slug = "01-the-record" if level == 1 else "02-the-method" if level == 2 else "03-research-comparison"
                path = ROOT / "notebooks" / language / topic / (slug + ".ipynb")
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(json.dumps(lesson_doc(language, topic, level, lesson), ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
                what = lesson["objective"]
                sections.append(f"- [{lesson['title']}]({topic}/{slug}.ipynb), level {level}: {what}\n")
            sections.append("\n")
        # Preserve separately authored advanced topics (for example optimization and uncertainty) when the
        # core lesson generator is rerun; notebooks remain the source of truth for those curriculum entries.
        extra_topics = sorted(p for p in (ROOT / "notebooks" / language).iterdir()
                              if p.is_dir() and p.name not in LESSONS)
        for extra_number, folder in enumerate(extra_topics, len(LESSONS) + 1):
            sections.append(f"## {extra_number:02d} {folder.name}\n")
            for path in sorted(folder.glob("*.ipynb")):
                notebook = json.loads(path.read_text(encoding="utf-8"))
                level = int(notebook["metadata"]["caos"]["level"])
                title = notebook["metadata"]["caos"]["title"]
                objective_heading = "## Objetivos" if language == "es" else "## Objectives"
                objective = next("".join(cell["source"]).split("\n\n", 1)[1]
                                 for cell in notebook["cells"]
                                 if cell["cell_type"] == "markdown"
                                 and "".join(cell["source"]).startswith(objective_heading))
                sections.append(f"- [{title}]({folder.name}/{path.name}), level {level}: {objective.strip()}\n")
            sections.append("\n")
        (ROOT / "notebooks" / language / "README.md").write_text("\n".join(sections).rstrip() + "\n", encoding="utf-8")

if __name__ == "__main__":
    main()
